package br.com.sussmartcare.clinicalquery.infrastructure; import org.apache.kafka.common.TopicPartition; import org.springframework.context.annotation.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.*; import org.springframework.util.backoff.FixedBackOff; @Configuration public class KafkaErrorConfig {@Bean DefaultErrorHandler kafkaErrorHandler(KafkaTemplate<Object,Object> template){var recoverer=new DeadLetterPublishingRecoverer(template,(r,e)->new TopicPartition(r.topic()+".DLT",r.partition()));return new DefaultErrorHandler(recoverer,new FixedBackOff(1000L,2L));}}
